from modele import chapitre,E,Q,tableau

chapitre(7,'proportionnalite','Proportionnalité, rapports et ratios','2 · Algèbre et modèles',
'Quatrième proportionnelle · Égalité de rapports · Ratios · Partages',
['Reconnaître une proportionnalité et calculer une quatrième proportionnelle.','Comparer deux nombres ou deux grandeurs par un rapport ou un ratio.','Résoudre des problèmes de partage proportionnel.'],
['Proportionnalité, tableaux et graphiques (Cinquième), fractions.'],[
r'''\essSection{1}{Coefficients et égalité des rapports}
\begin{definition}Deux grandeurs sont proportionnelles si l’on passe des valeurs de la première à celles de la seconde en multipliant toujours par un même nombre, le coefficient de proportionnalité. Quand les deux grandeurs sont de natures différentes, ce coefficient a une unité : 2,50 €/kg, 80 km/h.\end{definition}
\begin{propriete}[Égalité des rapports]Si $(a\,;b)$ et $(c\,;d)$ sont deux couples de valeurs correspondantes de grandeurs proportionnelles, avec $b\ne0$ et $d\ne0$, alors $\frac ab=\frac cd$. Pour $b\ne0$ et $d\ne0$, l’égalité $\frac ab=\frac cd$ équivaut à $a\times d=b\times c$ : les produits en croix sont égaux.\end{propriete}
\begin{exemple}4 cahiers identiques coûtent 10 €. Prix de 7 cahiers ? Retour à l’unité : un cahier coûte 2,50 €, donc 7 cahiers coûtent $7\times2{,}50=17{,}50$ €. Produits en croix : $\frac4{10}=\frac7p$ donne $4p=70$, donc $p=17{,}50$ €.\end{exemple}
\begin{attention}Un tarif de 5 € fixes plus 2 € par article n’est pas proportionnel : doubler le nombre d’articles ne double pas le prix. Une proportionnalité se représente par des points alignés avec l’origine. Le produit en croix n’est qu’une méthode : linéarité et retour à l’unité restent valables.\end{attention}''',
r'''\essSection{2}{Rapports, ratios et partages}
\begin{definition}Le rapport de deux nombres, ou de deux grandeurs de même nature, $a$ et $b$ ($b\ne0$) est le quotient $\frac ab$ : il permet de les comparer. On emploie aussi le mot ratio. Les nombres $a$ et $b$ sont dans le ratio $3:5$ lorsque $\frac a3=\frac b5$ ; $a$, $b$, $c$ sont dans le ratio $2:3:7$, ou proportionnels à 2, 3, 7, lorsque $\frac a2=\frac b3=\frac c7$.\end{definition}
\begin{savoirfaire}[Partager selon un ratio]Pour partager 56 dans le ratio $3:5$, on compte $3+5=8$ parts égales. Une part vaut $56:8=7$. Les deux quantités sont $3\times7=21$ et $5\times7=35$. Contrôle : $21+35=56$ et $\frac{21}3=\frac{35}5=7$.\end{savoirfaire}
@FIG:cours-ratio@
\begin{exemple}[Une échelle est un rapport]À l’échelle $1:500$, aussi notée $\frac1{500}$, 1 cm sur le plan représente 500 cm en réalité : on compare deux longueurs exprimées dans la même unité.\end{exemple}
\begin{attention}L’ordre compte : le ratio $3:5$ n’est pas le ratio $5:3$. Dans un partage selon $3:5$, la première part représente $\frac38$ du total, et non $\frac35$.\end{attention}'''],[
E('Passer à l’unité',r"Six bouteilles identiques coûtent 9 euros. Combien coûtent dix bouteilles, sans frais fixes ?",r"Une bouteille coûte $9:6=1{,}50$ euro. Dix bouteilles coûtent $10\times1{,}50=\res{15}$ euros. On suppose le prix unitaire constant.","Calculer le prix d’une unité.","assert Rational(9,6)*10==15"),
E('Compléter un tableau',r"Le prix est proportionnel à la masse. Compléter le tableau."+tableau(['Masse (kg)','2','5','8'],[['Prix (euros)','7','?','?']]),r"Le coefficient masse vers prix est $\frac72=3{,}5$ euros par kg. Les prix sont donc $5\times3{,}5=\res{17{,}50}$ euros et $8\times3{,}5=\res{28}$ euros.","Préciser le sens et l’unité du coefficient.","assert 5*Rational(7,2)==Rational('17.5') and 8*Rational(7,2)==28"),
E('Des produits en croix',r"Les couples $(6\,;15)$ et $(8\,;x)$ sont des valeurs correspondantes de deux grandeurs proportionnelles. Calculer $x$ avec l’égalité des produits en croix, puis vérifier avec le coefficient.",r"$\frac6{15}=\frac8x$ donne $6x=15\times8=120$, donc $\res{x=20}$. Vérification : le coefficient vaut $\frac{15}6=2{,}5$ et $8\times2{,}5=20$.","Écrire l’égalité des rapports avant le produit en croix.","assert solve(6*x-15*8,x)==[20] and 8*Rational(15,6)==20"),
E('Un ratio dans une classe',r"Dans une classe de 28 élèves, il y a 12 filles. Donner le rapport du nombre de filles au nombre de garçons, puis le ratio filles : garçons sous forme simplifiée.",r"Il y a $28-12=16$ garçons. Le rapport vaut $\frac{12}{16}=\res{\frac34}$. Le ratio filles : garçons est $12:16$, soit $\res{3:4}$ : pour 3 filles, il y a 4 garçons.","Comparer les deux groupes, pas une partie au total.","assert Rational(12,28-12)==Rational(3,4)"),
E('Lire une échelle',r"Sur un plan à l’échelle $1:500$, un mur mesure 3,6 cm. Quelle longueur réelle représente-t-il, en mètres ?",r"La longueur réelle est $3{,}6\times500=1\,800$ cm, soit $\res{18\ \mathrm m}$. La conversion en mètres vient après le calcul dans la même unité.","Faire d’abord le rapport avec des unités identiques.","assert Rational('3.6')*500/100==18"),
E('Une quatrième proportionnelle',r"Huit pièces identiques pèsent 14,4 kg. Quelle est la masse de cinq pièces ? Donner deux méthodes.",r"Par unité : $14{,}4:8=1{,}8$ kg, puis $5\times1{,}8=\res9$ kg. Par produits en croix : $\frac8{14{,}4}=\frac5m$ donne $8m=72$, donc $m=9$ kg. Les deux méthodes concordent.","Comparer passage à l’unité et produits en croix.","assert 5*Rational('14.4')/8==9"),
E('Un tarif non proportionnel',r"Un service facture 4 euros fixes puis 3 euros par heure. Calculer pour 1 h et 2 h. Le prix est-il proportionnel au temps ?",r"Pour 1 h : $4+3=\res7$ euros. Pour 2 h : $4+6=\res{10}$ euros. Doubler le temps ne double pas 7 euros, donc il n’y a $\res{\text{pas proportionnalité}}$. Les frais fixes l’empêchent.","Tester un doublement.","assert 4+3==7 and 4+3*2==10 and 10!=2*7"),
E('Un graphique',r"Le graphique représente un prix en fonction d’une masse. Reconnaître la proportionnalité et lire le prix de 3 kg.",r"Les points sont sur une droite passant par l’origine : le prix est proportionnel à la masse dans ce modèle. À 3 kg, l’ordonnée est $\res{7{,}50}$ euros. Le coefficient est 2,50 euros par kg.","Vérifier l’alignement avec l’origine puis lire les axes.","assert 3*Rational('2.5')==Rational('7.5')",figure='proportion-prix'),
E('Partager selon un ratio',r"Ana et Ben se partagent 72 euros dans le ratio $4:5$. Représenter le partage par un schéma en barres, puis calculer les deux parts.",r"On compte $4+5=9$ parts égales ; une part vaut $72:9=8$ euros. Ana reçoit $4\times8=\res{32}$ euros et Ben $5\times8=\res{40}$ euros. Contrôle : $32+40=72$ et $\frac{32}4=\frac{40}5$.","Compter les parts, puis calculer une part.","assert Rational(72,4+5)==8 and 4*8+5*8==72",figure='ratio-72'),
E('Trois nombres proportionnels',r"Les nombres $a$, $b$, $c$ sont proportionnels à 2, 3 et 7, et $a+b+c=60$. Calculer $a$, $b$ et $c$.",r"Le ratio $2:3:7$ compte $2+3+7=12$ parts. Une part vaut $60:12=5$. Donc $\res{a=10}$, $\res{b=15}$ et $\res{c=35}$. On vérifie $\frac{10}2=\frac{15}3=\frac{35}7=5$.","Utiliser le total des parts.","assert Rational(60,12)==5 and (2*5,3*5,7*5)==(10,15,35) and 10+15+35==60"),
E('Une recette et des lots',r"Une recette pour 6 personnes demande 450 g de farine. On la prépare pour 14 personnes. La farine est vendue en paquets de 500 g. Combien de paquets faut-il ?",r"Par personne, il faut $450:6=75$ g. Pour 14 personnes, $75\times14=1\,050$ g. Deux paquets ne donnent que 1 000 g : il faut $\res3$ paquets. La quantité achetée peut dépasser la quantité nécessaire.","Calculer la quantité puis arrondir le nombre de lots vers le haut.","assert 450*Rational(14,6)==1050 and ceil(Rational(1050,500))==3"),
E('Une part connue',r"Trois amis se partagent des cartes dans le ratio $4:3:2$. Le deuxième en reçoit 18. Combien les deux autres en reçoivent-ils ? Combien y a-t-il de cartes en tout ?",r"Le deuxième a 3 parts, donc une part vaut $18:3=6$ cartes. Le premier reçoit $4\times6=\res{24}$ cartes, le troisième $2\times6=\res{12}$ cartes. Le total est $9\times6=\res{54}$ cartes.","Retrouver la valeur d’une part à partir de la part connue.","assert 18//3==6 and 4*6==24 and 2*6==12 and 24+18+12==54"),
E('Un arc de cercle',r"Un cercle de rayon 6 cm porte un arc de mesure $75^\circ$. Calculer la longueur de cet arc, exactement puis au dixième de cm.",r"La longueur d’un arc est proportionnelle à son angle. La circonférence vaut $2\pi\times6=12\pi$ cm pour $360^\circ$. L’arc mesure donc $12\pi\times\frac{75}{360}=\res{\frac{5\pi}2\ \mathrm{cm}}$, soit environ $\res{7{,}9\ \mathrm{cm}}$.","Prendre la fraction d’un tour complet.","assert simplify(12*pi*Rational(75,360))==5*pi/2 and round(float(5*pi/2),1)==7.9",figure='arc-75'),
E('Un mélange de peinture',r"Une teinte s’obtient en mélangeant peinture bleue et peinture blanche dans le ratio $2:5$. On dispose de 3 L de bleu. Quelle quantité de blanc faut-il ? Quel volume de mélange obtient-on ? Quelle fraction du mélange est bleue ?",r"Le bleu représente 2 parts, donc une part vaut $3:2=1{,}5$ L. Il faut $5\times1{,}5=\res{7{,}5\ \mathrm L}$ de blanc. Le mélange mesure $3+7{,}5=\res{10{,}5\ \mathrm L}$. Le bleu représente $\res{\frac27}$ du mélange, car $2+5=7$ parts.","Distinguer le ratio entre deux couleurs et la fraction du total.","assert Rational(3,2)*5==Rational('7.5') and 3+Rational('7.5')==Rational('10.5') and Rational(3)/Rational('10.5')==Rational(2,7)"),
E('Comparer deux recettes',r"La recette A utilise 250 g de farine pour 0,5 L de lait ; la recette B 400 g de farine pour 0,75 L de lait. Laquelle contient le plus de farine par litre de lait ? Avec B, quelle masse de farine faut-il pour 1,2 L de lait ?",r"A : $250:0{,}5=500$ g/L. B : $400:0{,}75\approx533$ g/L. La recette $\res{B}$ est la plus riche en farine. Pour 1,2 L avec B : $\frac{400\times1{,}2}{0{,}75}=\res{640\ \mathrm g}$. Comparer les seules masses de farine n’aurait pas suffi, car les volumes de lait diffèrent.","Comparer des quantités rapportées à un litre.","assert Rational(250)/Rational('0.5')==500 and Rational(400)/Rational('0.75')>500 and 400*Rational('1.2')/Rational('0.75')==640")
],reperes=['Quatrième proportionnelle et produits en croix','Rapports, ratios et échelles','Partages proportionnels','Graphiques et grandeurs non proportionnelles'],deco='courbe')

chapitre(8,'grandeurs','Pourcentages et grandeurs quotients','2 · Algèbre et modèles',
'Coefficient multiplicateur · Vitesse · Débit · Masse volumique',
['Calculer avec des pourcentages et un coefficient multiplicateur.','Calculer et interpréter une grandeur quotient avec son unité.','Convertir des durées, des vitesses et des débits.'],
['Proportionnalité et rapports (chapitre 7), conversions usuelles.'],[
r'''\essSection{1}{Pourcentages et coefficient multiplicateur}
\begin{propriete}Prendre $t\,\%$ d’une quantité revient à la multiplier par $\frac t{100}$. Pour exprimer une part en pourcentage, on divise la partie par le total : 28 élèves sur 80, c’est $\frac{28}{80}=0{,}35=35\,\%$.\end{propriete}
\begin{definition}Augmenter une grandeur de $t\,\%$ revient à la multiplier par $1+\frac t{100}$ ; la diminuer de $t\,\%$ revient à la multiplier par $1-\frac t{100}$. Ce nombre est le coefficient multiplicateur : $1{,}15$ pour une hausse de 15\,\%, $0{,}8$ pour une baisse de 20\,\%.\end{definition}
\begin{exemple}Un article de 60 € baisse de 15\,\% : il coûte $60\times0{,}85=51$ €. La baisse vaut $60-51=9$ €, soit bien $\frac{15}{100}\times60$. Retrouver le prix initial à partir de 51 € revient à diviser par 0,85.\end{exemple}
\begin{attention}Pour deux évolutions successives, on multiplie les coefficients : une baisse de 20\,\% puis de 10\,\% donne $0{,}8\times0{,}9=0{,}72$, soit une baisse de 28\,\% et non de 30\,\%. Pour réunir deux groupes, on revient aux effectifs avant de calculer un pourcentage.\end{attention}''',
r'''\essSection{2}{Grandeurs quotients}
\begin{definition}Une grandeur quotient est le quotient de deux grandeurs ; son unité combine les deux unités. Vitesse moyenne : $v=\frac dt$, en km/h ou m/s. Débit : $q=\frac Vt$, en L/min. Masse volumique : $\rho=\frac mV$, en g/cm$^3$. Prix au kilogramme : en €/kg.\end{definition}
\begin{exemple}Parcourir 150 km en 2 h 30 min donne $t=2{,}5$ h, puis $v=\frac{150}{2{,}5}=60$ km/h. Un robinet qui fournit 12 L en 40 s a un débit de $\frac{12}{40}=0{,}3$ L/s.\end{exemple}
\begin{savoirfaire}[Choisir des unités cohérentes]$1$ h $=60$ min $=3\,600$ s ; 1 h 30 min vaut 1,5 h et non 1,30 h. $1$ km/h $=\frac{1\,000}{3\,600}$ m/s : pour passer de km/h à m/s, on divise par 3,6. $1$ L $=1$ dm$^3$ et $1$ m$^3=1\,000$ L. On convertit séparément les deux unités d’une grandeur quotient.\end{savoirfaire}
\begin{attention}La vitesse moyenne d’un aller-retour n’est pas en général la moyenne des deux vitesses : on divise la distance totale par la durée totale. Écrire les unités à côté des données permet de contrôler un résultat.\end{attention}'''],[
E('Une part en pourcentage',r"Calculer 18\,\% de 250.",r"$18\,\%=\frac{18}{100}$. La part cherchée vaut $\frac{18}{100}\times250=\res{45}$.","Multiplier la quantité par la fraction correspondante.","assert Rational(18,100)*250==45"),
E('Retrouver le pourcentage',r"Dans un groupe de 32 élèves, 12 sont demi-pensionnaires. Quel pourcentage cela représente-t-il ?",r"Le rapport partie sur total est $\frac{12}{32}=0{,}375$. Il correspond à $\res{37{,}5\,\%}$. Le dénominateur est l’effectif total, pas celui des autres élèves.","Diviser la partie par le total.","assert Rational(12,32)*100==Rational('37.5')"),
E('Des coefficients',r"Donner le coefficient multiplicateur associé à une hausse de 15\,\%, une baisse de 20\,\%, une hausse de 3\,\% et une baisse de 7,5\,\%.",r"Hausse : $1+\frac{t}{100}$ ; baisse : $1-\frac{t}{100}$. On obtient $\res{1{,}15}$, $\res{0{,}8}$, $\res{1{,}03}$ et $\res{0{,}925}$. Un coefficient inférieur à 1 traduit une baisse.","Ajouter ou retrancher la part en centièmes à 1.","assert (1+Rational(15,100),1-Rational(20,100),1+Rational(3,100),1-Rational('7.5')/100)==(Rational('1.15'),Rational('0.8'),Rational('1.03'),Rational('0.925'))"),
E('Une vitesse moyenne',r"Un cycliste parcourt 45 km en 2 h 30 min. Calculer sa vitesse moyenne.",r"$2$ h $30$ min $=2{,}5$ h. La vitesse moyenne est $45:2{,}5=\res{18\ \mathrm{km/h}}$.","Exprimer la durée dans l’unité du quotient.","assert 45/Rational('2.5')==18"),
E('Une durée',r"Convertir 2 h 18 min en heures décimales et en minutes.",r"$18$ min $=\frac{18}{60}=0{,}3$ h, donc la durée vaut $\res{2{,}3\ \mathrm h}$. En minutes : $2\times60+18=\res{138}$ min.","Utiliser une heure de 60 minutes.","assert 2+Rational(18,60)==Rational('2.3') and 2*60+18==138"),
E('Une remise',r"Un sac coûte 80 euros. On lui applique une remise de 12\,\%. Calculer son nouveau prix avec un coefficient multiplicateur.",r"Le coefficient vaut $1-0{,}12=0{,}88$. Le nouveau prix est $80\times0{,}88=\res{70{,}40}$ euros. La remise vaut 9,60 euros.","Multiplier directement par le coefficient.","assert 80*(1-Rational(12,100))==Rational('70.4')"),
E('Une hausse de loyer',r"Un loyer de 640 euros augmente de 2,5\,\%. Calculer le nouveau loyer avec un coefficient multiplicateur, puis le montant de la hausse.",r"Le coefficient vaut $1+0{,}025=1{,}025$. Le nouveau loyer est $640\times1{,}025=\res{656}$ euros. La hausse vaut $656-640=\res{16}$ euros, soit $\frac{2{,}5}{100}\times640$.","Associer la hausse au coefficient supérieur à 1.","assert 640*Rational('1.025')==656 and Rational('2.5')/100*640==16"),
E('Une conversion de vitesse',r"Convertir 72 km/h en m/s.",r"72 km correspondent à $72\,000$ m en 3 600 s. Donc $72\,000:3\,600=\res{20\ \mathrm{m/s}}$. On retrouve $72:3{,}6=20$.","Convertir distance et durée.","assert Rational(72000,3600)==20"),
E('Changer les deux unités',r"Convertir un débit de $0{,}012$ m$^3$/s en L/min.",r"On convertit d’abord le volume : $0{,}012$ m$^3$/s $=12$ L/s. En une minute, il s’écoule $12\times60=\res{720\ \mathrm{L/min}}$. Une minute contient davantage de volume qu’une seconde.","Convertir séparément le volume et le temps de référence.","assert Rational('.012')*1000*60==720"),
E('Une masse volumique',r"Une pièce a un volume de 40 cm$^3$ et une masse de 108 g. Calculer sa masse volumique, puis la masse d’une pièce de 65 cm$^3$ du même matériau.",r"$\rho=\frac{108}{40}=\res{2{,}7\ \mathrm{g/cm}^3}$ : chaque cm$^3$ pèse 2,7 g. À masse volumique identique, $m=2{,}7\times65=\res{175{,}5}$ g.","Calculer le quotient puis réutiliser le coefficient.","assert Rational(108,40)==Rational('2.7') and Rational(108,40)*65==Rational('175.5')"),
E('Deux remises successives',r"Un article de 100 euros subit une baisse de 20\,\%, puis une baisse de 10\,\% du nouveau prix. Quel prix obtient-on ? La baisse totale vaut-elle 30\,\% ?",r"Les coefficients se multiplient : $100\times0{,}8\times0{,}9=\res{72}$ euros. Le coefficient global $0{,}72$ correspond à une baisse de $\res{28\,\%}$, et non de 30\,\% : la seconde baisse porte sur 80 euros.","Multiplier les coefficients successifs.","assert 100*(1-Rational(20,100))*(1-Rational(10,100))==72"),
E('Un pourcentage inverse',r"Après une remise de 25\,\%, un objet coûte 54 euros. Retrouver son prix avant remise.",r"Le prix payé est le prix initial $P$ multiplié par 0,75 : $0{,}75P=54$, d’où $P=54:0{,}75=\res{72}$ euros. Vérification : 25\,\% de 72 vaut 18, et $72-18=54$.","Diviser par le coefficient multiplicateur.","assert Rational(54)/Rational(75,100)==72"),
E('Deux groupes réunis',r"Un club compte 20 jeunes dont 40\,\% de filles, et 30 adultes dont 60\,\% de femmes. Quel est le pourcentage de personnes de sexe féminin dans le club ?",r"Il y a $20\times0{,}4=8$ filles et $30\times0{,}6=18$ femmes, soit 26 personnes sur 50. Le pourcentage est $\frac{26}{50}=\res{52\,\%}$. La moyenne simple de 40\,\% et 60\,\% ignorerait les effectifs différents.","Revenir aux effectifs avant de réunir les groupes.","assert (20*Rational(40,100)+30*Rational(60,100))/50==Rational(52,100)"),
E('Aller et retour',r"Un trajet de 30 km est parcouru à 15 km/h à l’aller et à 30 km/h au retour. Calculer la vitesse moyenne sur l’ensemble du trajet.",r"L’aller dure $30:15=2$ h et le retour $30:30=1$ h. Pour 60 km en 3 h, la vitesse moyenne vaut $\res{20\ \mathrm{km/h}}$. La moyenne simple 22,5 ne tient pas compte des durées différentes.","Diviser la distance totale par la durée totale.","assert 60/(Rational(30,15)+Rational(30,30))==20"),
E('Une comparaison de débits',r"La pompe A débite 900 L/min ; la pompe B débite $0{,}018$ m$^3$/s. Laquelle est la plus rapide ? Combien de minutes gagne-t-elle pour pomper 5 400 L ?",r"B débite $0{,}018\times1\,000\times60=\res{1\,080}$ L/min, donc plus que A. A met $5\,400:900=6$ min ; B met $5\,400:1\,080=5$ min. Le gain est de $\res1$ min.","Comparer dans une même unité puis calculer les durées.","assert Rational('.018')*1000*60==1080 and Rational(5400,900)-Rational(5400,1080)==1")
],reperes=['Pourcentages et coefficient multiplicateur','Évolutions successives et réciproques','Vitesses, durées et distances','Débits, masses volumiques et conversions'],deco='calcul')

chapitre(9,'fonctions','Programmes de calcul et dépendance','2 · Algèbre et modèles',
'Programmes · Formules · Tableaux · Graphiques',
['Appliquer un programme de calcul à un nombre, puis à une lettre.','Remonter un programme pour retrouver le nombre de départ.','Traduire la dépendance de deux grandeurs par une formule, un tableau et un graphique.'],
['Repérage dans le plan, calcul littéral et équations.'],[
r'''\essSection{1}{Des programmes de calcul aux formules}
\begin{definition}Un programme de calcul enchaîne des opérations à partir d’un nombre de départ. Appliqué à une lettre, il produit une expression littérale qui donne le résultat pour tous les nombres de départ à la fois.\end{definition}
\begin{exemple}Programme : choisir un nombre ; soustraire 4 ; multiplier le résultat par 3. Avec 10 : $10-4=6$, puis $6\times3=18$. Avec $x$ : $3(x-4)=3x-12$. On retrouve 18 pour $x=10$ : $3\times10-12=18$.\end{exemple}
\begin{savoirfaire}[Remonter un programme]Pour retrouver le nombre de départ qui donne 9, on effectue les opérations inverses dans l’ordre inverse : $9:3=3$, puis $3+4=7$. Contrôle : $(7-4)\times3=9$. On peut aussi résoudre l’équation $3(x-4)=9$.\end{savoirfaire}
\begin{definition}[Une notation]Quand une grandeur $P$ dépend d’une grandeur $t$, on note $P(t)$ sa valeur pour une valeur donnée de $t$. Si $P(t)=6+2t$ est le prix en euros d’une location de $t$ heures, $P(3)=12$ se lit « $P$ de 3 égale 12 » : trois heures coûtent 12 €.\end{definition}
\begin{attention}$P(3)$ n’est pas un produit : c’est la valeur de $P$ pour $t=3$. Le programme et la formule décrivent la même dépendance ; le tableau et le graphique en montrent quelques valeurs.\end{attention}''',
r'''\essSection{2}{Tableaux et graphiques}
\begin{exemple}Pour $P(t)=6+2t$ : $P(0)=6$, $P(1)=8$, $P(2)=10$, $P(3)=12$. Les points de coordonnées $(t\,;P(t))$ sont placés dans un repère, la durée en abscisse et le prix en ordonnée.\end{exemple}
@FIG:cours-location@
\begin{savoirfaire}[Lire dans les deux sens]Partir d’une valeur de l’axe horizontal, rejoindre le tracé verticalement, puis lire l’axe vertical. Dans l’autre sens, suivre l’horizontale d’une valeur verticale jusqu’à toutes ses intersections avec le tracé.\end{savoirfaire}
\begin{propriete}Une situation de proportionnalité se représente par des points alignés avec l’origine. Ici $P(0)=6$ : le prix n’est pas proportionnel à la durée. L’aire $A(c)=c^2$ d’un carré de côté $c$ se représente par une courbe : ce n’est pas une proportionnalité.\end{propriete}
\begin{attention}Lire d’abord les graduations et les unités. Une lecture graphique est souvent approchée et ne vaut que dans le domaine représenté.\end{attention}'''],[
E('Appliquer un programme',r"Programme : choisir un nombre ; le multiplier par 3 ; soustraire 5 au résultat. Appliquer ce programme à 4, à $-2$ et à 1,5.",r"Pour 4 : $4\times3-5=\res7$. Pour $-2$ : $(-2)\times3-5=-6-5=\res{-11}$. Pour 1,5 : $4{,}5-5=\res{-0{,}5}$.","Effectuer les étapes dans l’ordre.","assert [3*a-5 for a in [4,-2,Rational('1.5')]]==[7,-11,Rational('-0.5')]"),
E('Du programme à l’expression',r"Programme : choisir un nombre ; lui ajouter 6 ; multiplier le résultat par $-2$. Écrire le résultat obtenu à partir de $x$, puis développer.",r"On ajoute 6 : $x+6$. On multiplie le résultat entier par $-2$ : $\res{-2(x+6)}$. En développant : $\res{-2x-12}$. Les parenthèses traduisent « le résultat ».","Placer des parenthèses autour du résultat intermédiaire.","assert expand(-2*(x+6))==-2*x-12"),
E('Remonter un programme',r"Programme : choisir un nombre ; soustraire 4 ; multiplier le résultat par 5. On obtient 35. Retrouver le nombre de départ de deux façons.",r"En remontant : $35:5=7$, puis $7+4=\res{11}$. Avec une équation : $5(x-4)=35$ donne $x-4=7$, donc $x=11$. Contrôle : $(11-4)\times5=35$.","Inverser les opérations dans l’ordre inverse.","assert solve(5*(x-4)-35,x)==[11]"),
E('Une formule de tarif',r"Une location coûte 5 euros fixes et 3 euros par heure. Exprimer le prix $P(t)$ pour $t$ heures, puis calculer $P(0)$, $P(2)$ et $P(4)$.",r"La partie fixe vaut 5 et la partie liée au temps $3t$ : $\res{P(t)=5+3t}$. On remplace $t$ : $P(0)=\res5$, $P(2)=5+6=\res{11}$ et $P(4)=5+12=\res{17}$ euros.","Additionner partie fixe et partie variable.","assert [5+3*a for a in [0,2,4]]==[5,11,17]"),
E('Lire un couple',r"Le graphique donne la température $T$ d’un four, en $^\circ$C, en fonction du temps en minutes. Lire $T(2)$.",r"On part de 2 sur l’axe du temps, on rejoint le tracé puis on lit l’axe vertical : $\res{T(2)=60\,^\circ\mathrm C}$. Les unités viennent des axes.","Suivre la verticale puis l’horizontale.","assert 20+20*2==60",figure='four'),
E('Lire une durée',r"Sur le même graphique, à quel instant la température atteint-elle $100\,^\circ$C pour la première fois ?",r"L’horizontale de niveau 100 coupe le tracé à l’abscisse $\res4$ min pour la première fois. On lit cette fois un temps, et non une température.","Partir cette fois de l’axe vertical.","assert 20+20*4==100",figure='four'),
E('Une lecture inverse double',r"Sur le graphique du four, donner tous les instants où la température vaut $60\,^\circ$C.",r"L’horizontale de niveau 60 coupe le tracé deux fois : à $\res2$ min pendant la chauffe et à $\res{10}$ min pendant le refroidissement. Il faut chercher toutes les intersections dans l’intervalle représenté.","Parcourir toute l’horizontale.","assert 20+20*2==60 and 160-10*10==60",figure='four'),
E('Reconnaître une relation',r"Le graphique représente-t-il une situation de proportionnalité ? Justifier.",r"La droite représentée passe par le point $(0\,;2)$, pas par l’origine. La relation n’est donc $\res{\text{pas proportionnelle}}$, même si les points sont alignés : pour zéro unité horizontale, la valeur verticale vaut déjà 2.","Vérifier le passage par l’origine.","assert (2+2*x).subs(x,0)==2",figure='graph-non-proportion'),
E('Construire un graphique',r"On vend une corde à 1,5 euro le mètre, pour des longueurs de 0 à 6 m. Compléter un tableau pour 0, 2, 4 et 6 m, puis tracer la représentation du prix en fonction de la longueur.",r"Les prix sont $\res{0,\ 3,\ 6,\ 9}$ euros. Les points $(0\,;0)$, $(2\,;3)$, $(4\,;6)$ et $(6\,;9)$ sont alignés avec l’origine : c’est une proportionnalité. La corde pouvant être achetée en longueur intermédiaire, on trace le segment correspondant.","Placer les couples avant de relier.","assert [Rational('1.5')*a for a in [0,2,4,6]]==[0,3,6,9]",figure='graph-corde'),
E('Aire d’un carré',r"Exprimer l’aire $A(c)$ d’un carré de côté $c$ cm. Calculer $A(1)$, $A(2)$, $A(3)$ et $A(4)$. L’aire est-elle proportionnelle au côté ?",r"$A(c)=c^2$. Les aires valent $\res{1,\ 4,\ 9,\ 16}$ cm$^2$. Doubler le côté de 1 à 2 multiplie l’aire par 4 et non par 2 : l’aire $\res{\text{n’est pas proportionnelle}}$ au côté. Les points ne sont pas alignés.","Comparer l’effet d’un doublement.","assert [a*a for a in [1,2,3,4]]==[1,4,9,16]",figure='graph-carre'),
E('Deux programmes égaux',r"Programme A : choisir un nombre ; ajouter 3 ; multiplier par 4 ; soustraire 12. Programme B : choisir un nombre ; le multiplier par 4. Montrer qu’ils donnent toujours le même résultat. Quel nombre de départ donne 26 ?",r"A donne $4(x+3)-12=4x+12-12=4x$, comme B : les programmes sont $\res{\text{équivalents}}$. Pour obtenir 26, on résout $4x=26$ : $\res{x=6{,}5}$.","Écrire les deux expressions avec la même lettre.","assert expand(4*(x+3)-12)==4*x and solve(4*x-26,x)==[Rational(13,2)]"),
E('Un tableur',r"Dans un tableur, A2 contient une durée en heures. Quelle formule saisir en B2 pour calculer le prix $P(t)=5+3t$, puis recopier vers le bas ? Quels prix s’affichent en B3 et B4 ?",r"On saisit $\res{\texttt{=5+3*A2}}$. Lors de la recopie, A2 devient A3, A4, etc. : B3 affiche $\res{11}$ et B4 affiche $\res{17}$. La référence relative suit la durée de chaque ligne ; les nombres 5 et 3 restent fixes.","Remplacer la lettre par la cellule de la ligne.","assert 5+3*2==11 and 5+3*4==17",figure='tableur-prix'),
E('Retirer des carrés',r"Dans un rectangle de 18 cm sur 10 cm, on retire aux quatre coins des carrés de côté $x$ cm, avec $0<x<5$. Exprimer l’aire restante $A(x)$, puis calculer $A(2)$.",r"L’aire initiale vaut 180 cm$^2$. Les quatre carrés retirent $4x^2$, donc $\res{A(x)=180-4x^2}$. Pour $x=2$, $A(2)=180-16=\res{164\ \mathrm{cm}^2}$. La condition $x<5$ évite que deux carrés d’un même petit côté se chevauchent.","Soustraire les quatre aires retirées.","assert (180-4*x**2).subs(x,2)==164",figure='coins-retires'),
E('Deux courbes de prix',r"Les graphiques correspondent aux prix $A(t)=4+2t$ et $B(t)=4t$, pour $0\le t\le4$ heures. Lire l’heure d’égalité, puis la vérifier par une équation.",r"Les tracés se coupent au point $(2\,;8)$. L’égalité $4+2t=4t$ donne $4=2t$, donc $\res{t=2}$ h et un prix de $\res8$ euros. Avant 2 h, B est moins cher ; après 2 h, A est moins cher sur l’intervalle étudié.","Confirmer la lecture par le calcul.","assert solve(4+2*x-4*x,x)==[2]",figure='graph-tarifs'),
E('Une réserve qui diminue',r"Une réserve contient 120 L ; on retire 8 L par minute à débit constant. Donner une formule du volume $V(t)$ après $t$ minutes et le domaine de validité de ce modèle.",r"Le volume restant est $\res{V(t)=120-8t}$ litres. Il s’annule pour $120-8t=0$, soit $t=15$ min. Le modèle de vidange est valable pour $\res{0\le t\le15}$ ; un volume négatif ne représente pas la situation.","Associer une formule à un domaine réaliste.","assert solve(120-8*x,x)==[15]",figure='graph-reserve')
],reperes=['Programmes de calcul et expressions','Remonter un programme','Formules, notation $P(t)$ et tableaux','Lectures graphiques et proportionnalité'],deco='courbe')
